    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 dep, uint256 am) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (dep)); require(dep <= 1000000000000000000000000000000);
        require(dep > 0 && dep <= 100 ether);
        require(am <= 200 ether);
        require(address(this).balance >= dep);

        c.Deposit{value: dep}(); if (__ESBMC_reverted()) return;
        uint256 balBefore = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 cBalBefore = address(c).balance;
        uint256 minSum = c.MinSum(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.Collect(am); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 balAfter = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 cBalAfter = address(c).balance;
        uint256 expectedBalAfter;
        if (balBefore >= minSum && balBefore >= am) {
            expectedBalAfter = balBefore - am;
        } else {
            expectedBalAfter = balBefore;
        }

        assert(reverted == !((balBefore >= minSum && balBefore >= am) ? (balAfter == expectedBalAfter) : (balAfter == balBefore)));
    }

    receive() external payable {}
